    dict(id="inscription-1601", title="The Deccan inscription on the Buland Darwaza", periodId="abandoned-1610", date="1601–02", kind="construction",
         at=dict(landmarkId="buland-darwaza"), effect="construction",
         text="After the fall of Asirgarh in the Deccan, Akbar is said to have passed by his old capital, and inscriptions dated 1601–02 were cut on the great gate recording his conquests and the saying attributed to Jesus: 'the world is a bridge, pass over it but build no house upon it.' Some take this as the gate's building date.",
         sourceIds=["wiki-buland-darwaza", "rizvi-flynn"]),
